// @ts-nocheck
import { useState, useEffect, useMemo, useCallback } from "react";

// ─── UTILITIES ────────────────────────────────────────────────────────────────
const rng = (s, e) => Array.from({ length: e - s + 1 }, (_, i) => s + i);
const rmN = s => (s || '').replace(/[\u0591-\u05C7]/g, '').trim();

function yearToHeb(year) {
  const y = year % 1000;
  const H = ['','ק','ר','ש','ת','תק','תר','תש','תת','תתק'];
  const T = ['','י','כ','ל','מ','נ','ס','ע','פ','צ'];
  const O = ['','א','ב','ג','ד','ה','ו','ז','ח','ט'];
  const h = Math.floor(y / 100), t = Math.floor((y % 100) / 10), o = y % 10;
  let r = H[h];
  if (t === 1 && o === 5) return r + 'ט"ו';
  if (t === 1 && o === 6) return r + 'ט"ז';
  r += T[t];
  if (!o) return r.length > 1 ? r.slice(0,-1) + '"' + r.slice(-1) : r + "'";
  return r + '"' + O[o];
}

function toHebNum(n) {
  if (n === 15) return 'ט"ו'; if (n === 16) return 'ט"ז';
  const o = ['', 'א', 'ב', 'ג', 'ד', 'ה', 'ו', 'ז', 'ח', 'ט'];
  const t = { 10: 'י', 20: 'כ', 30: 'ל' };
  if (n < 10) return o[n]; if ([10, 20, 30].includes(n)) return t[n];
  return t[Math.floor(n / 10) * 10] + '"' + o[n % 10];
}

const EN_HE = {
  Tishri: 'תשרי', Heshvan: 'חשוון', Cheshvan: 'חשוון', Marcheshvan: 'חשוון',
  Kislev: 'כסלו', Tevet: 'טבת', Shevat: 'שבט',
  Adar: 'אדר', 'Adar I': 'אדר א', 'Adar II': 'אדר ב',
  Nisan: 'ניסן', Iyar: 'אייר', Sivan: 'סיוון', Tammuz: 'תמוז', Av: 'אב', Elul: 'אלול'
};

function hebInfo(date) {
  try {
    const parts = new Intl.DateTimeFormat('en-u-ca-hebrew', {
      year: 'numeric', month: 'long', day: 'numeric'
    }).formatToParts(date).reduce((a, p) => ({ ...a, [p.type]: p.value }), {});
    const mName = EN_HE[parts.month] || parts.month;
    const mDisp = rmN(new Intl.DateTimeFormat('he-IL-u-ca-hebrew', { month: 'long' }).format(date));
    const hDay = parseInt(parts.day) || 1;
    const hYear = parseInt(parts.year) || 5784;
    const yStr = yearToHeb(hYear);
    return { hDay, hYear, mName, mDisp, yStr, dayStr: toHebNum(hDay) };
  } catch { return { hDay: 1, hYear: 5784, mName: '', mDisp: '', yStr: '', dayStr: 'א' }; }
}

