// ─── CALENDAR LOGIC ───────────────────────────────────────────────────────────
function buildMonth(year, month) {
  const cnt = new Date(year, month, 0).getDate();
  return Array.from({ length: cnt }, (_, i) => {
    const day = i + 1;
    const date = new Date(year, month - 1, day);
    const hi = hebInfo(date);
    const vac = VACATIONS.find(v => v.m === hi.mName && v.d.includes(hi.hDay));
    const not = !vac && NOTABLE.find(v => v.m === hi.mName && v.d.includes(hi.hDay));
    const intl = INTL.filter(d => d.month === month && d.day === day);
    return {
      day, dow: date.getDay(), isShab: date.getDay() === 6,
      isVac: !!vac, vacName: vac?.n,
      isNot: !!not, notName: not?.n,
      intl: intl.map(d => d.name), ...hi
    };
  });
}

function getLabels(year, month) {
  const fi = hebInfo(new Date(year, month - 1, 1));
  const li = hebInfo(new Date(year, month, 0));
  let heText;
  if (fi.mName === li.mName) heText = `${fi.mDisp} ${fi.yStr}`;
  else if (fi.hYear === li.hYear) heText = `${fi.mDisp}–${li.mDisp} ${fi.yStr}`;
  else heText = `${fi.mDisp} ${fi.yStr} – ${li.mDisp} ${li.yStr}`;
  return { heText, grMonth: MONTHS_HE[month - 1] };
}

