// ─── APP ──────────────────────────────────────────────────────────────────────
const PrintableCalendar = () => {
  const today = new Date();
  const [year, setYear] = useState(today.getFullYear());
  const [month, setMonth] = useState(today.getMonth() + 1);
  const [allEvts, setAllEvts] = useState({});
  const [selDay, setSelDay] = useState(null);
  const [newEvt, setNewEvt] = useState('');
  const [tab, setTab] = useState('custom');

  const storeKey = `hcal_v1_${year}_${month}`;

  useEffect(() => {
    try { const s = localStorage.getItem(storeKey); setAllEvts(s ? JSON.parse(s) : {}); }
    catch { setAllEvts({}); }
  }, [storeKey]);

  const save = useCallback((evts) => {
    setAllEvts(evts);
    try { localStorage.setItem(storeKey, JSON.stringify(evts)); } catch {}
  }, [storeKey]);

  useEffect(() => {
    const el = document.createElement('style');
    el.textContent = PRINT_CSS;
    document.head.appendChild(el);
    return () => document.head.removeChild(el);
  }, []);

  useEffect(() => { setSelDay(null); }, [year, month]);

  const days = useMemo(() => buildMonth(year, month), [year, month]);
  const labels = useMemo(() => getLabels(year, month), [year, month]);
  const offset = new Date(year, month - 1, 1).getDay();
  const numRows = Math.ceil((offset + days.length) / 7);

  const grid = useMemo(() => {
    const g = Array(offset).fill(null);
    days.forEach(d => g.push(d));
    while (g.length % 7 !== 0) g.push(null);
    return g;
  }, [days, offset]);

  const rows = useMemo(() => {
    const rs = [];
    for (let i = 0; i < grid.length; i += 7) rs.push(grid.slice(i, i + 7));
    return rs;
  }, [grid]);

  const dayEvts = d => allEvts[d] || [];

  const addEvt = (day, text) => {
    if (!text?.trim()) return;
    save({ ...allEvts, [day]: [...dayEvts(day), { text: text.trim() }] });
    setNewEvt('');
  };

  const delEvt = (day, idx) => {
    const evts = dayEvts(day).filter((_, i) => i !== idx);
    const n = { ...allEvts };
    if (!evts.length) delete n[day]; else n[day] = evts;
    save(n);
  };

  const selInfo = selDay ? days.find(d => d.day === selDay) : null;
  const monthIntl = INTL.filter(d => d.month === month);
  const cellH = numRows <= 5 ? 100 : 86;

  const [showWelcome, setShowWelcome] = useState(() => {
    try { return !localStorage.getItem('hcal_welcomed'); } catch { return true; }
  });
  const closeWelcome = () => {
    try { localStorage.setItem('hcal_welcomed', '1'); } catch {}
    setShowWelcome(false);
  };

  const dark = '#1a1a2e';
  const C = {
    shab: '#f0f0f0', shab_bd: '#c8c8c8',
    vac: '#fef7e6',  vac_bd: '#e8c54a',
    not: '#eef6ff',  not_bd: '#b0d0f0',
  };

  const handlePrint = useCallback(() => {
    const calEl = document.querySelector('.cal-card');
    if (!calEl) return;
    const pw = window.open('', '_blank', 'width=1200,height=860');
    if (!pw) { alert('אנא אפשר חלונות קופצים בדפדפן ולחץ שוב הדפס'); return; }
    pw.document.write(`<!DOCTYPE html>
<html dir="rtl"><head><meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
<style>
@page{size:A4 landscape;margin:1cm}
*{box-sizing:border-box;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}
body{font-family:'Heebo',Arial,sans-serif;margin:0;padding:0;direction:rtl;background:white}
.cal-card{width:100%!important;max-width:100%!important;height:184mm!important;overflow:hidden!important;
  display:flex!important;flex-direction:column!important;border-radius:0!important;
  box-shadow:none!important;border:1px solid #ccc!important}
.cal-grid{flex:1!important;display:flex!important;flex-direction:column!important;overflow:hidden!important}
.cal-row{flex:1!important;display:grid!important;grid-template-columns:repeat(7,1fr)!important}
.cal-cell{overflow:hidden!important}
</style></head><body>${calEl.outerHTML}</body></html>`);
    pw.document.close();
    pw.onload = () => { pw.focus(); setTimeout(() => pw.print(), 400); };
  }, []);

  return (
    <div dir="rtl" style={{ fontFamily: "'Heebo', Arial, sans-serif", minHeight: '100vh', background: '#eeece8' }}>

      {/* CONTROLS */}
      <div className="no-print" style={{
        background: 'white', borderBottom: '1px solid #e0e0e0', padding: '10px 20px',
        display: 'flex', alignItems: 'center', gap: '14px', flexWrap: 'wrap', justifyContent: 'space-between'
      }}>
        <span style={{ fontWeight: 800, fontSize: '16px', color: dark, letterSpacing: '-0.3px' }}>
          לוח שנה להדפסה
        </span>

        <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
          <select value={month} onChange={e => setMonth(+e.target.value)}
            style={{ padding: '6px 10px', border: '1px solid #ddd', borderRadius: '7px', fontSize: '13px', direction: 'rtl', fontFamily: 'inherit', background: 'white', cursor: 'pointer' }}>
            {MONTHS_HE.map((n, i) => <option key={i} value={i + 1}>{n}</option>)}
          </select>
          <input type="number" value={year} onChange={e => setYear(+e.target.value)} min="2020" max="2060"
            style={{ width: '82px', padding: '6px', border: '1px solid #ddd', borderRadius: '7px', fontSize: '13px', textAlign: 'center', fontFamily: 'inherit' }} />
          <button onClick={handlePrint}
            style={{ background: dark, color: 'white', border: 'none', borderRadius: '7px', padding: '7px 18px', fontSize: '13px', cursor: 'pointer', fontFamily: 'inherit', fontWeight: 600 }}>
            הדפס
          </button>
          <span style={{ fontSize: '10px', color: '#aaa', maxWidth: 140, lineHeight: 1.4 }}>
            בחלון ההדפסה — בטל "כותרות ועמודות תחתונות"
          </span>
        </div>

        <div style={{ display: 'flex', gap: '12px', fontSize: '11px', color: '#666' }}>
          {[
            { bg: C.shab, bd: C.shab_bd, label: 'שבת' },
            { bg: C.vac,  bd: C.vac_bd,  label: 'יום חופשה' },
            { bg: C.not,  bd: C.not_bd,  label: 'מועד מיוחד' },
          ].map((l, i) => (
            <span key={i} style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
              <span style={{ width: 13, height: 13, background: l.bg, border: `1px solid ${l.bd}`, borderRadius: 3, display: 'inline-block' }} />
              {l.label}
            </span>
          ))}
        </div>
      </div>

      {/* CALENDAR */}
      <div className="screen-wrap" style={{ padding: '16px', display: 'flex', justifyContent: 'center' }}>
        <div className="cal-card" style={{
          background: 'white', width: '100%', maxWidth: '1100px',
          boxShadow: '0 2px 20px rgba(0,0,0,0.1)', borderRadius: '10px',
          border: '1px solid #e8e8e8', overflow: 'hidden',
          display: 'flex', flexDirection: 'column', position: 'relative'
        }}>

          {/* Header */}
          <div style={{
            display: 'flex', justifyContent: 'space-between', alignItems: 'baseline',
            padding: '13px 22px 10px', borderBottom: '1.5px solid #c0c0be'
          }}>
            <div style={{ fontSize: '28px', fontWeight: 800, color: dark, letterSpacing: '-0.5px' }}>
              {labels.grMonth} {year}
            </div>
            <div style={{ fontSize: '16px', fontWeight: 500, color: '#5a6375', letterSpacing: '0.3px' }}>
              {labels.heText}
            </div>
          </div>

          {/* Day name row */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7,1fr)', background: '#e4e4e2', borderBottom: '1px solid #c0c0be' }}>
            {DAYS_HE.map((n, i) => (
              <div key={i} style={{
                textAlign: 'center', padding: '6px 2px', fontSize: '12px', fontWeight: 700,
                color: i === 6 ? '#555' : dark,
                borderRight: i < 6 ? '1px solid #ccccca' : undefined,
                background: i === 6 ? '#d4d4d2' : undefined
              }}>{n}</div>
            ))}
          </div>

          {/* Grid */}
          <div className="cal-grid" style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
            {rows.map((row, ri) => (
              <div key={ri} className="cal-row" style={{
                display: 'grid', gridTemplateColumns: 'repeat(7,1fr)',
                flex: 1, borderTop: '1px solid #e0e0de'
              }}>
                {row.map((d, ci) => {
                  if (!d) return (
                    <div key={ci} style={{
                      background: '#f8f8f6',
                      borderRight: ci < 6 ? '1px solid #e0e0de' : undefined
                    }} />
                  );
                  const evts = dayEvts(d.day);
                  const isToday = d.day === today.getDate() && month === today.getMonth() + 1 && year === today.getFullYear();
                  const bg = d.isShab ? C.shab : d.isVac ? C.vac : d.isNot ? C.not : 'white';

                  return (
                    <div key={ci} className="cal-cell"
                      onClick={() => { setSelDay(d.day); setNewEvt(''); setTab('custom'); }}
                      style={{
                        background: bg, borderRight: ci < 6 ? '1px solid #e0e0de' : undefined,
                        padding: '4px 7px', cursor: 'pointer', display: 'flex',
                        flexDirection: 'column', gap: '1px', minHeight: `${cellH}px`,
                        overflow: 'hidden', transition: 'filter .12s'
                      }}
                      onMouseEnter={e => e.currentTarget.style.filter = 'brightness(.96)'}
                      onMouseLeave={e => e.currentTarget.style.filter = ''}
                    >
                      {/* Day numbers */}
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                        {isToday ? (
                          <span style={{ background: '#c0392b', color: 'white', borderRadius: '50%', width: 22, height: 22, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, fontWeight: 700 }}>{d.day}</span>
                        ) : (
                          <span style={{ fontSize: 17, fontWeight: d.isShab ? 700 : 500, color: dark, lineHeight: 1 }}>{d.day}</span>
                        )}
                        <span style={{ fontSize: 10, color: '#b0b0b0', lineHeight: 1, paddingTop: 2 }}>{d.dayStr}</span>
                      </div>

                      {/* Holiday / notable */}
                      {(d.vacName || d.notName) && (
                        <div style={{ fontSize: 8.5, fontWeight: 700, lineHeight: 1.25, color: d.isVac ? '#8B1A1A' : '#1a4a6e', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                          {d.vacName || d.notName}
                        </div>
                      )}

                      {/* User events */}
                      {evts.map((ev, i) => (
                        <div key={i} style={{ fontSize: 8.5, color: '#1a4a6a', lineHeight: 1.2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                          • {ev.text}
                        </div>
                      ))}
                    </div>
                  );
                })}
              </div>
            ))}
          </div>

          {/* Season illustration */}
          <div style={{ position: 'absolute', bottom: 5, left: 7, zIndex: 0, pointerEvents: 'none' }}>
            <SeasonImg month={month} />
          </div>
        </div>
      </div>

      {/* EVENT MODAL */}
      {selDay && selInfo && (
        <div className="no-print"
          onClick={e => e.target === e.currentTarget && setSelDay(null)}
          style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.52)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
          <div dir="rtl" style={{
            background: 'white', borderRadius: 14, padding: 22, width: 400,
            maxWidth: '94vw', maxHeight: '84vh', overflowY: 'auto',
            boxShadow: '0 14px 50px rgba(0,0,0,.24)', fontFamily: "'Heebo', Arial"
          }}>
            {/* Day preview */}
            {(() => {
              const bg = selInfo.isShab ? C.shab : selInfo.isVac ? C.vac : selInfo.isNot ? C.not : 'white';
              const evts = dayEvts(selDay);
              return (
                <div style={{ background: bg, border: '1px solid #ddd', borderRadius: 10, padding: '10px 14px', marginBottom: 16 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 4 }}>
                    <span style={{ fontSize: 22, fontWeight: 700, color: dark, lineHeight: 1 }}>{selDay}</span>
                    <div style={{ textAlign: 'left' }}>
                      <div style={{ fontSize: 11, color: '#aaa' }}>{selInfo.dayStr}</div>
                      <div style={{ fontSize: 11, color: '#888' }}>{selInfo.mDisp} {selInfo.yStr}</div>
                    </div>
                  </div>
                  <div style={{ fontSize: 13, color: '#666', marginBottom: 2 }}>{MONTHS_HE[month - 1]} {year} · {DAYS_HE[selInfo.dow]}</div>
                  {(selInfo.vacName || selInfo.notName) && (
                    <div style={{ fontSize: 12, fontWeight: 700, color: selInfo.isVac ? '#8B1A1A' : '#1a4a6e', marginTop: 4 }}>
                      {selInfo.vacName || selInfo.notName}
                    </div>
                  )}
                  {evts.length > 0 && (
                    <div style={{ marginTop: 6, borderTop: '1px solid rgba(0,0,0,.08)', paddingTop: 6 }}>
                      {evts.map((ev, i) => (
                        <div key={i} style={{ fontSize: 12, color: '#1a4a6a', lineHeight: 1.5 }}>• {ev.text}</div>
                      ))}
                    </div>
                  )}
                  {evts.length === 0 && !selInfo.vacName && !selInfo.notName && (
                    <div style={{ fontSize: 11, color: '#bbb', marginTop: 4 }}>אין תוכן עדיין</div>
                  )}
                </div>
              );
            })()}

            {/* Existing events */}
            {dayEvts(selDay).length > 0 && (
              <div style={{ marginBottom: 14 }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: '#555', marginBottom: 7, textTransform: 'uppercase', letterSpacing: '.4px' }}>עריכת אירועים</div>
                {dayEvts(selDay).map((ev, i) => (
                  <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '7px 11px', background: '#f6f6f4', borderRadius: 8, marginBottom: 5, fontSize: 13 }}>
                    <span>{ev.text}</span>
                    <button onClick={() => delEvt(selDay, i)}
                      style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#c0392b', fontSize: 16, padding: '0 3px', lineHeight: 1 }}>×</button>
                  </div>
                ))}
              </div>
            )}

            {/* Tabs */}
            <div style={{ display: 'flex', gap: 6, marginBottom: 12, borderBottom: '1px solid #eee', paddingBottom: 10 }}>
              {[['custom', 'אירוע חופשי'], ['intl', `ימים בינ"ל (${monthIntl.length})`]].map(([key, label]) => (
                <button key={key} onClick={() => setTab(key)} style={{
                  background: tab === key ? dark : '#eeeeec', color: tab === key ? 'white' : '#444',
                  border: 'none', borderRadius: 7, padding: '6px 13px', fontSize: 12,
                  cursor: 'pointer', fontFamily: 'inherit', fontWeight: 500
                }}>{label}</button>
              ))}
            </div>

            {/* Custom event input */}
            {tab === 'custom' && (
              <div>
                <div style={{ display: 'flex', gap: 8, marginBottom: 8 }}>
                  <input value={newEvt} onChange={e => setNewEvt(e.target.value)}
                    onKeyDown={e => e.key === 'Enter' && addEvt(selDay, newEvt)}
                    placeholder="שם האירוע (טיול, אירוע, יום מיוחד...)"
                    autoFocus
                    style={{ flex: 1, padding: '9px 13px', border: '1px solid #ddd', borderRadius: 8, fontSize: 13, fontFamily: 'inherit', direction: 'rtl' }} />
                  <button onClick={() => addEvt(selDay, newEvt)}
                    style={{ background: dark, color: 'white', border: 'none', borderRadius: 8, padding: '9px 15px', cursor: 'pointer', fontSize: 13, fontFamily: 'inherit', fontWeight: 600 }}>
                    הוסף
                  </button>
                </div>
                <div style={{ fontSize: 11, color: '#aaa' }}>לחץ Enter להוספה מהירה</div>
              </div>
            )}

            {/* International days */}
            {tab === 'intl' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 5, maxHeight: 220, overflowY: 'auto' }}>
                {monthIntl.length === 0 ? (
                  <div style={{ fontSize: 13, color: '#999', padding: '8px 0' }}>אין ימים בינלאומיים רשומים החודש</div>
                ) : monthIntl.map((id, i) => (
                  <div key={i} style={{
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                    padding: '7px 11px', borderRadius: 8, fontSize: 12,
                    background: id.day === selDay ? '#ebf5fb' : '#f6f6f4',
                    border: id.day === selDay ? '1px solid #3498db' : '1px solid transparent'
                  }}>
                    <span style={{ flex: 1 }}>{id.day}/{month} – {id.name}</span>
                    <button onClick={() => addEvt(id.day, id.name)}
                      style={{ background: '#2980b9', color: 'white', border: 'none', borderRadius: 6, padding: '4px 10px', cursor: 'pointer', fontSize: 11, fontFamily: 'inherit', whiteSpace: 'nowrap', marginRight: 0 }}>
                      הוסף
                    </button>
                  </div>
                ))}
              </div>
            )}

            <button onClick={() => setSelDay(null)} style={{
              width: '100%', marginTop: 16, padding: 10, background: '#eeeeec',
              border: 'none', borderRadius: 8, cursor: 'pointer', fontSize: 14,
              fontFamily: 'inherit', color: '#333', fontWeight: 500
            }}>
              סגור
            </button>
          </div>
        </div>
      )}

      {/* WELCOME MODAL */}
      {showWelcome && (
        <div className="no-print"
          style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.55)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 2000 }}>
          <div dir="rtl" style={{
            background: 'white', borderRadius: 16, padding: '32px 28px', width: 440,
            maxWidth: '94vw', boxShadow: '0 16px 60px rgba(0,0,0,.28)', fontFamily: "'Heebo', Arial"
          }}>
            <div style={{ fontSize: 26, fontWeight: 800, color: dark, marginBottom: 8, letterSpacing: '-0.5px' }}>
              לוח שנה להדפסה
            </div>
            <div style={{ width: 40, height: 3, background: '#e8c54a', borderRadius: 2, marginBottom: 18 }} />
            <p style={{ fontSize: 14, color: '#444', lineHeight: 1.75, margin: '0 0 18px' }}>
              לרשותכם כלי להפקת לוח חודשי עברי ולועזי מודפס.
              הכלי מאפשר הוספת אירועים, תזכורות ומידע לכל יום,
              ואפשרות הדפסת הלוח בגודל A4 לרוחב.
            </p>
            <div style={{ background: '#f7f7f5', borderRadius: 10, padding: '12px 16px', marginBottom: 22, fontSize: 13, color: '#666', lineHeight: 1.65 }}>
              <span style={{ fontWeight: 700, color: dark }}>שימו לב: </span>
              המידע שתוסיפו נשמר בדפדפן שלכם בלבד ואינו מועלה לשום שרת.
            </div>
            <div style={{ fontSize: 13, color: '#888', marginBottom: 6 }}>
              <b style={{ color: '#444' }}>לחיצה על יום</b> — הוספת אירועים ותוכן
            </div>
            <div style={{ fontSize: 13, color: '#888', marginBottom: 22 }}>
              <b style={{ color: '#444' }}>כפתור הדפס</b> — פותח חלון הדפסה מוכן ל-A4
            </div>
            <button onClick={closeWelcome} style={{
              width: '100%', padding: '13px', background: dark, color: 'white',
              border: 'none', borderRadius: 10, cursor: 'pointer', fontSize: 15,
              fontFamily: 'inherit', fontWeight: 700, letterSpacing: '0.2px'
            }}>
              התחל
            </button>
          </div>
        </div>
      )}
    </div>
  );
}


export default PrintableCalendar;
